        maxFrequency = Math.max(maxFrequency, count);
        currentNode = currentNode.right;
    }

    for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
        if (entry.getValue() == maxFrequency) modes.add(entry.getKey());
    }

    return modes;
}
