class Solution {
    public String smallestStringWithSwaps(String s, int[][] pairs) {
        int n = s.length();
        int[] parent = new int[n];
        int[] rank = new int[n];

        // Initialize parent and rank arrays
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 1;
        }

        // Union operation with path compression and union by rank
        for (int[] pair : pairs) {
            union(pair[0], pair[1], parent, rank);
        }

        // Group characters by their root parent
        Map<Integer, PriorityQueue<Character>> groups = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int root = find(i, parent);
            groups.computeIfAbsent(root, k -> new PriorityQueue<>()).add(s.charAt(i));
        }

        // Reconstruct the smallest string
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            int root = find(i, parent);
            sb.append(groups.get(root).poll());
        }

        return sb.toString();
    }

    private int find(int x, int[] parent) {
        if (parent[x] != x) {
            parent[x] = find(parent[x], parent); // Path compression
        }
        return parent[x];
    }

